```go
// Register adds one or more TypeSpec to the registry.
func (r *TypeRegistry) Register(specs ...*TypeSpec) error {
    for _, s := range specs {
        if err := validSpec(s); err != nil {
            return fmt.Errorf("specutil: invalid typespec %q: %w", s.Name, err)
